    T("host", "那 Agent 就是拿三样东西去补这三个洞？"),
    T("guest", "别急着一一对应，会说错。是三件事在撑着那个闭环。第一件是工具调用，让它从说话变成做事。这里有个最容易误解的地方 ——"),
