    T("guest", "模型变强只是三分之一。第一，模型能力跨过了「能用」的门槛。早期模型你让它做任务拆解、判断下一步调哪个工具，它根本做不好；从 GPT-4、Claude 3 这一代开始，推理和指令遵循能力有质的飞跃。"),
