    T("host", "那假设有 5 个框架、8 个工具……就是 40 套？"),
    T("guest", "算得倒是快。M 个框架乘 N 个工具，这就是所谓的 M 乘 N 适配爆炸。MCP 的做法是定义一套标准的 JSON-RPC 协议，工具方按标准把能力暴露出来变成一个 Server，任何支持 MCP 的 Agent 通过内置的 Client 直接发现和调用，不用再写适配代码。"),
    T("host", "那不就是给 Agent 的工具世界立了个 USB-C 标准。"),
    T("guest", "业界就是这么类比的。它的架构分三层，面试最爱追：最外层是 Host，用户直接交互的 AI 应用；中间是 Client，负责建连接、管通信；最里层是 Server，真正暴露工具能力的服务。这三层背不下来，就别说自己懂 MCP。"),
