# ── 讲稿体检 ──────────────────────────────────────────────────────

META_PATTERNS = [
    (r"不用再回去翻原文|不必再翻原文|不用看原文|替代阅读", "把节目定位当台词说了"),
    (r"听众看不到|听不到|音频里|这档节目的目标|这一季的目标", "点破媒介限制或制作意图"),
    (r"你口述一下|念一下代码|读一下这段代码", "像给嘉宾的导演指令"),
]


def lint(strict: bool = False) -> int:
    """检查讲稿里有没有把制作意图写进台词。返回问题数。"""
    problems = 0
    for n in sorted(EPISODES):
        for i, turn in enumerate(EPISODES[n]["turns"]):
            for pat, why in META_PATTERNS:
                if re.search(pat, turn["t"]):
                    problems += 1
                    print(f"  ✗ ep{n:02d} 第 {i} 轮 [{turn['s']}] {why}")
                    print(f"      {turn['t'][:60]}")
    print("  ✓ 讲稿体检通过，无越界台词" if not problems else f"  共 {problems} 处")
    if problems and strict:
        sys.exit("讲稿体检未通过")
    return problems


def stats() -> None:
    print(f"{'集':>3}{'轮次':>6}{'字数':>7}{'时长':>8}   标题")
    tt = tc = 0
    for n in sorted(EPISODES):
        e = EPISODES[n]
        c = sum(len(t["t"]) for t in e["turns"])
        tt += len(e["turns"]); tc += c
        print(f"{n:>3}{len(e['turns']):>6}{c:>7}{c / CHARS_PER_MIN:>7.1f}m   {e['title'][:30]}")
    print(f"\n  合计 {len(EPISODES)} 集 / {tt} 轮 / {tc} 字 / 约 {tc / CHARS_PER_MIN:.0f} 分钟")
    print(f"  TTS 请求数 = 轮次数 = {tt}（每轮一次，失败可命中缓存不重复计费）")


# ── TTS ──────────────────────────────────────────────────────────

def load_api_key() -> str:
    if not ENV_FILE.exists():
        sys.exit("缺少 .env（FISH_KEY=...）")
    for line in ENV_FILE.read_text().splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        if k.strip() in ("FISH_KEY", "FISH_API_KEY"):
            return v.strip().strip('"').strip("'")
    sys.exit(".env 里没有 FISH_KEY")


def turn_offsets(wavs: list[Path], turns: list[dict]) -> tuple[list[int], int]:
    """按 concat_wavs 的拼接方式精确算出每轮的起始毫秒。

    concat 是采样级拼接，静音长度用 int(framerate * sec) 帧，
    这里用同样的整数运算，结果与最终 wav 逐帧一致。
    """
    import wave
    off, frames = [], 0
    for i, (w, turn) in enumerate(zip(wavs, turns)):
        off.append(round(frames * 1000 / SAMPLE_RATE))
        with wave.open(str(w), "rb") as f:
            if f.getframerate() != SAMPLE_RATE:
                raise RuntimeError(f"采样率不符: {w.name}")
            # Fish Audio 返回流式 wav，头里 nframes 是占位符（0x7FFFFF80），
            # 只能按实际读到的字节数算。concat_wavs 同样是读到 EOF，两者一致。
            n = len(f.readframes(f.getnframes())) // (f.getnchannels() * f.getsampwidth())
            if n == 0:
                raise RuntimeError(f"空 wav: {w.name}")
            frames += n
        if i + 1 < len(turns):
            gap = GAP_SAME_SEC if turns[i + 1]["s"] == turn["s"] else GAP_SWITCH_SEC
            frames += int(SAMPLE_RATE * gap)
    return off, round(frames * 1000 / SAMPLE_RATE)


def annotate(n: int, wavs: list[Path]) -> int:
    """把时间轴写进 turns（字段 ms），返回总时长毫秒。"""
    turns = EPISODES[n]["turns"]
    off, total = turn_offsets(wavs, turns)
    for turn, ms in zip(turns, off):
        turn["ms"] = ms
    EPISODES[n]["ms"] = total
    return total


def annotate_from_cache() -> int:
    """用 .tts-cache 里的分句 wav 补时间轴，不调 API。返回补齐的集数。"""
    done = 0
    for n in sorted(EPISODES):
        turns = EPISODES[n]["turns"]
        wavs = [cache_key(t["t"], HOST_VOICE if t["s"] == "host" else GUEST_VOICE)
                for t in turns]
        if not all(w.exists() and w.stat().st_size > 1000 for w in wavs):
            continue
        annotate(n, wavs)
        done += 1
    return done


def lrc_path(n: int) -> Path:
    return (APP / EPISODES[n]["audio"]).with_suffix(".lrc")


def write_lrc(n: int) -> Path | None:
    """导出 LRC。没有时间轴就跳过。"""
    e = EPISODES[n]
    turns = e["turns"]
    if any("ms" not in t for t in turns):
        return None
    lines = [f"[ti:第 {n} 集 {e['title']}]",
             f"[ar:{HOST_NAME} & {GUEST_NAME}]",
             f"[al:{SERIES}]", "[by:gen_podcast_renna.py]", ""]
    for t in turns:
        cs = t["ms"] // 10
        mm, rest = divmod(cs, 6000)
        name = HOST_NAME if t["s"] == "host" else GUEST_NAME
        lines.append(f"[{mm:02d}:{rest // 100:02d}.{rest % 100:02d}]{name}：{t['t']}")
    dest = lrc_path(n)
    dest.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return dest


def dump_json() -> None:
    old = {}
    if OUT_JSON.exists():
        try:
            old = json.loads(OUT_JSON.read_text(encoding="utf-8"))
        except Exception:
            old = {}
    decks = old.get("decks", {}) if isinstance(old, dict) else {}
    decks[CURRENT_DECK] = {str(n): EPISODES[n] for n in sorted(EPISODES)}
    payload = {
        "version": 1,
        "series": SERIES,
        "speakers": {
            "host": {"name": HOST_NAME, "role": HOST_ROLE},
            "guest": {"name": GUEST_NAME,
                      "role": GUEST_ROLE_BY_DECK.get(CURRENT_DECK, GUEST_ROLE)},
        },
        "voices": {"host": HOST_VOICE, "guest": GUEST_VOICE},
        "decks": decks,
    }
    OUT_JSON.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"wrote {OUT_JSON.name}  ({OUT_JSON.stat().st_size} bytes, {len(EPISODES)} episodes)")


def cache_key(text: str, voice: str) -> Path:
    import hashlib
    h = hashlib.sha256(f"{TTS_MODEL}|{voice}|{SAMPLE_RATE}|{text}".encode()).hexdigest()[:24]
    return CACHE_DIR / f"{h}.wav"


def tts_one(client, key: str, text: str, voice_id: str, dest: Path) -> bool:
    """合成单轮。命中缓存返回 False（未计费），实际请求返回 True。"""
    cached = cache_key(text, voice_id)
    if cached.exists() and cached.stat().st_size > 1000:
        dest.write_bytes(cached.read_bytes())
        return False

    body = {
        "text": text,
        "reference_id": voice_id,
        "format": "wav",
        "sample_rate": SAMPLE_RATE,
        "latency": "normal",
        "normalize": True,
        "temperature": 0.55,
        "top_p": 0.7,
        "chunk_length": 300,
        "prosody": {"speed": 1, "volume": 0, "normalize_loudness": True},
    }
    last_err = None
    for attempt in range(4):
        try:
            res = client.post(
                TTS_URL,
                headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json",
                         "model": TTS_MODEL},
                json=body, timeout=180.0,
            )
            if res.status_code == 429:
                wait = 8 * (attempt + 1)
                print(f"    429，等 {wait}s", flush=True)
                time.sleep(wait)
                continue
            if res.status_code >= 400:
                raise RuntimeError(f"HTTP {res.status_code}: {res.text[:300]}")
            if len(res.content) < 1000 or res.content[:4] != b"RIFF":
                raise RuntimeError(f"返回不是 wav: {len(res.content)} bytes")
            CACHE_DIR.mkdir(parents=True, exist_ok=True)
            cached.write_bytes(res.content)
            dest.write_bytes(res.content)
            return True
        except Exception as e:
            last_err = e
            wait = 4 * (attempt + 1)
            print(f"    重试 {attempt + 1}: {e}  等 {wait}s", flush=True)
            time.sleep(wait)
    raise RuntimeError(last_err)


def concat_wavs(parts: list[Path], dest: Path, gaps: list[float]) -> None:
    import wave
    with wave.open(str(parts[0]), "rb") as first:
        params = first.getparams()
        frames = [first.readframes(first.getnframes())]
    bpf = params.nchannels * params.sampwidth

    def silence(sec: float) -> bytes:
        return b"\x00" * (max(0, int(params.framerate * sec)) * bpf)

    for i, p in enumerate(parts[1:], 1):
        frames.append(silence(gaps[i - 1]))
        with wave.open(str(p), "rb") as w:
            if (w.getnchannels(), w.getsampwidth(), w.getframerate()) != (
                params.nchannels, params.sampwidth, params.framerate):
                raise RuntimeError(f"wav 参数不一致: {p.name}")
            frames.append(w.readframes(w.getnframes()))
    with wave.open(str(dest), "wb") as out:
        out.setparams(params)
        out.writeframes(b"".join(frames))


def wav_to_mp3(wav_path: Path, mp3_path: Path) -> None:
    subprocess.check_call([LAME, "--silent", "-b", "64", "-m", "m", str(wav_path), str(mp3_path)])


def generate(only: set[int] | None, force: bool, workers: int) -> None:
    import httpx
    from concurrent.futures import ThreadPoolExecutor, as_completed
    lock = threading.Lock()
    key = load_api_key()
    AUDIO_DIR.mkdir(parents=True, exist_ok=True)
    nums = [n for n in sorted(EPISODES) if not only or n in only]
    billed = hits = 0
    limits = httpx.Limits(max_connections=workers, max_keepalive_connections=workers)
    with httpx.Client(limits=limits) as client:
        for n in nums:
            e = EPISODES[n]
            dest = APP / e["audio"]
            if not force and dest.exists() and dest.stat().st_size > 10_000:
                print(f"skip {dest.name}（已存在）", flush=True)
                continue
            turns = e["turns"]
            print(f"ep {n:02d}  {len(turns)} 轮 / {sum(len(t['t']) for t in turns)} 字 -> {dest.name}", flush=True)
            with tempfile.TemporaryDirectory() as td:
                parts = [Path(td) / f"{i:03d}.wav" for i in range(1, len(turns) + 1)]

                def synth(i: int) -> bool:
                    turn = turns[i]
                    voice = HOST_VOICE if turn["s"] == "host" else GUEST_VOICE
                    t0 = time.time()
                    fresh = tts_one(client, key, turn["t"], voice, parts[i])
                    with lock:
                        done[0] += 1
                        tag = "API" if fresh else "缓存"
                        print(f"  {done[0]}/{len(turns)} #{i+1:03d} {turn['s']:<5} "
                              f"{len(turn['t']):>3}字 [{tag}] {time.time()-t0:.1f}s", flush=True)
                    return fresh

                done = [0]
                with ThreadPoolExecutor(max_workers=workers) as pool:
                    futs = {pool.submit(synth, i): i for i in range(len(turns))}
                    for fut in as_completed(futs):
                        fresh = fut.result()   # 任一轮彻底失败则整集中止，不产出残缺音频
                        billed += fresh; hits += (not fresh)

                missing = [p for p in parts if not p.exists() or p.stat().st_size < 1000]
                if missing:
                    raise RuntimeError(f"ep {n} 有 {len(missing)} 轮未产出 wav")
                gaps = [GAP_SAME_SEC if a["s"] == b["s"] else GAP_SWITCH_SEC
                        for a, b in zip(turns, turns[1:])]
                wav_out = Path(td) / "episode.wav"
                concat_wavs(parts, wav_out, gaps)
                wav_to_mp3(wav_out, dest)
                total = annotate(n, parts)
                write_lrc(n)
            print(f"  saved {dest.name} ({dest.stat().st_size} bytes, "
                  f"{total // 60000}:{total // 1000 % 60:02d}) + {lrc_path(n).name}", flush=True)
    print(f"\n  本次实际调用 API {billed} 次，命中缓存 {hits} 次")
    dump_json()   # 把新算出的时间轴写回 json



