    T("guest", "具体做法是让两个 token 的位置编码只取决于它们的差值，跟各自的绝对值无关。这是 RoPE 和 ALiBi 共同的出发点，只是实现路线不同。"),
    T("host", "那 RoPE 是怎么做的？"),
    T("guest", "二零二一年，中国学者苏剑林提出的——核心就一句话：不把位置信息加到 embedding 上，而是旋转 Q 和 K 向量。"),
    T("host", "旋转……怎么个转法？"),
    T("guest", "每个 token 的 Q、K 向量，根据它的位置被旋转一个对应角度——位置零不转，位置一转一个角度，位置二转两个，依此类推。"),
    T("host", "那我想象成……钟表的指针？位置越靠后，指针转得越多。"),
