    T("guest", "位置 m 的 Q 和位置 n 的 K 做点积，旋转之后的结果只跟 m 减 n 有关，跟 m 和 n 各自的绝对值无关。"),
    T("host", "哦——！相对位置就这么天然地编进 Attention 里了，模型根本不用学。"),
    T("guest", "这是 RoPE 区别于 sin/cos 的核心。还有三个优点呢，一个一个说。"),
