    T("host", "那外推能力呢？sin/cos 就是栽在这儿的。"),
    T("guest", "RoPE 的旋转是连续的角度变化，本身没有「训练截止」这个概念。训练只见过两千，推理来了四千——"),
    T("host", "多出来的位置只是更大的旋转角度而已，模型不会彻底懵。"),
