    T("guest", "二零二三年之后基本全部——Llama 全系、Qwen 全系、DeepSeek 的 V1 到 V3 和 R1、Mistral 和 Mixtral、GLM 系列。事实标准。"),
    T("host", "那第三种，ALiBi 呢？"),
    T("guest", "二零二二年提出的——思路比 RoPE 还暴力：根本不动 Q、K、V。"),
    T("host", "那它动什么呢？"),
    T("guest", "直接在注意力分数里加一个距离惩罚项——离得越远，扣分越多。"),
