    T("guest", "而且长上下文外推天然就好，因为距离惩罚本身就是个连续函数。"),
    T("host", "听着也不错啊。那为什么没成主流？"),
    T("guest", "表达力弱一些。它对位置的精细建模不如 RoPE——毕竟只是一个线性的扣分，信息量有限。"),
