    T("host", "比如说？"),
    T("guest", "比如 t 和 h 经常在一起，就把它们合并成一个新 token「th」，加进词汇表。"),
    T("host", "然后语料里所有 t、h 相邻的地方都换成 th？"),
    T("guest", "然后继续找下一个最高频的对。比如 th 和 e 合并成 the。"),
    T("host", "哦——！每轮合并产生一条规则，词汇表就多一个 token。那什么时候停？"),
    T("guest", "第三步：重复到词汇表达到预设大小。GPT-2 用了五万零两百五十七，第三代 Llama 用了十二万八千。"),
