    T("guest", "给每个回答打分。可以用奖励模型，也可以直接用对错判定——数学题对了给一分，错了给零分。"),
    T("host", "然后呢？基线从哪儿来？"),
    T("guest", "从这八个回答自己身上来——用组内的相对排名做基线。"),
    T("host", "……哦！不需要另一个模型去估「平均水平」，因为这八个回答的平均就是平均！"),
    T("guest", "组内归一化——这就是「Group Relative」这个名字的来源。"),
    T("host", "省掉一整个和主模型一样大的网络……显存能省多少？"),
    T("guest", "大致减半——而且省掉了 Value Model 的训练成本和调参。"),
    T("host", "谁在用？"),
