    T("guest", "拒绝采样——这个最朴素，你听名字猜猜。"),
    T("host", "拒绝……采样？生成一堆然后把不好的拒绝掉？"),
    T("guest", "对每个问题生成多个回答，用奖励模型筛出高分的，然后再做一轮 SFT。"),
    T("host", "所以流程里根本没有 RL？"),
    T("guest", "就是「生成、筛选、再 SFT」的循环。第二代 Llama 的对齐流程里就用了这个。"),
    T("host", "这么简单也有用？"),
    T("guest", "简单不等于没用——这是很多团队在没有 RL 工程能力时的现实选择。最后一类，RLAIF。"),
    T("host", "AI Feedback……用 AI 代替人类标注偏好？"),
    T("guest", "Anthropic 的 Constitutional AI、Google 的相关工作里都有它的影子。"),
    T("host", "优点是标注成本低、可以批量生成偏好数据。那缺点呢？"),
    T("guest", "你自己想——它靠什么打分。"),
    T("host", "靠一个更强的 AI……所以它依赖一个「教师 AI」。"),
    T("guest", "教师不行，学生也就到那儿了——五类讲完了，现在回答最开始那个问题。"),
    T("host", "家族图谱？"),
    T("guest", "这五类是互相替代的关系吗。"),
    T("host", "呃……我本来以为是。RLHF 太重，所以有了 DPO；PPO 要 Value Model，所以有了 GRPO……"),
    T("guest", "那第二代 Llama 用了几种。"),
    T("host", "SFT、拒绝采样、PPO——三种！"),
    T("guest", "DeepSeek R1 呢。"),
    T("host", "SFT 冷启动、GRPO 多轮迭代、拒绝采样筛数据……也是组合。"),
    T("guest", "所以真实的对齐流程通常是组合使用的。这就是这道题的收口。"),
    T("host", "把它们当成互斥选项，就答错了。"),
    T("guest", "面试官问「你了解哪些 Post-Training 方法」，你要是背五个名字，那是及格。你要是能说出「它们通常怎么组合」——"),
    T("host", "那才像做过项目的人。"),
    T("guest", "……这句话你偷我的。"),
    T("host", "陈述事实而已——那明天组会我怎么讲？"),
    T("guest", "先说 Post-Training 是个上位概念，不是单一方法。再说 SFT 之后差什么——质量偏好和安全对齐两个缺口。"),
    T("host", "然后五类各自的位置：RLHF 上限高但四个模型太重；DPO 省一半模型但没有探索能力；GRPO 砍掉 Value Model 用组内相对排名做基线；拒绝采样最朴素；RLAIF 省标注但依赖教师。"),
    T("guest", "最后落到组合——别落到「选哪个」。"),
    T("host", "学费——今天算了一笔：我们要是真上 RLHF，光四个模型的显存，就超我们全部预算能租到的卡。"),
    T("guest", "……这算数据。那你们的现实选项是什么。"),
    T("host", "偏好数据要是能攒出来，就 DPO；攒不出来，先拒绝采样。"),
    T("guest", "这个判断是对的。而且你注意到了——你不是在选最好的，是在选你付得起的。"),
