    T("guest", "所以你现在知道为什么很多团队宁可用拒绝采样了。"),
    T("host", "……因为偏好数据本身就是奢侈品。"),
    T("guest", "这一条你自己想出来的，比我讲的管用。明天换个方向——模型是怎么把字一个一个吐出来的。解码策略。"),
