    T("host", "那除了复读，还有别的问题吗？"),
    T("guest", "更隐蔽的——生成的文本乏味、保守、缺乏惊喜。"),
    T("host", "为什么？"),
    T("guest", "每步都选最稳的那条路，最终生成的就是「最大众化的表达」。"),
    T("host", "读起来很无聊……那贪心是不是就没用了？"),
    T("guest", "……它有它的最佳战场。你猜是什么任务。"),
    T("host", "呃……需要确定性的？"),
    T("guest", "精确任务——代码生成、SQL 生成、JSON 抽取这种「输出有标准答案」的。"),
    T("host", "哦——！这种任务本来就不需要创意，确定、不乱写才是优点。"),
    T("guest", "所以别把贪心当成「落后方案」，它只是有明确的适用面。第二种，Beam Search。"),
    T("host", "它是贪心的扩展版？"),
    T("guest", "每一步不只保留一条路径，而是保留若干条最高概率的路径同时推进。"),
