    T("host", "然后一直重复到遇到结束符，最后从三条里选整体概率乘积最高的那条。"),
    T("guest", "它的优点是什么。"),
    T("host", "全局视野更好？某一步贪心选错了，它还有其他备份路径可以走。"),
    T("guest", "总体概率上比贪心高得多，输出更「合理」。所以它在哪个时代是绝对主流。"),
    T("host", "翻译？"),
    T("guest", "二零一四到二零一八年的机器翻译时代，几乎所有翻译模型都用它。"),
    T("host", "为什么翻译特别适合？"),
    T("guest", "翻译任务有一个独特属性——给定源语言句子，存在一个或几个「最优译文」。"),
    T("host", "所以「找概率最高序列」这个目标，和翻译任务高度匹配！"),
    T("guest", "那到了 LLM 时代呢。"),
    T("host", "你刚才说几乎被弃用了……可我还是觉得「更准」应该是好事啊。"),
